const fetchTodos = () => async (dispatch, getState) => {
  dispatch({ type: 'todos/loading' });
  const res = await fetch('/api/todos');
  dispatch({ type: 'todos/loaded', payload: await res.json() });
};
dispatch(fetchTodos());

export const fetchTodos = createAsyncThunk('todos/fetch', async () => {
  const res = await fetch('/api/todos');
  return res.json();
});
// generates: todos/fetch/pending, todos/fetch/fulfilled, todos/fetch/rejected

extraReducers: (builder) => {
  builder
    .addCase(fetchTodos.pending, (state) => { state.status = 'loading'; })
    .addCase(fetchTodos.fulfilled, (state, action) => {
      state.status = 'idle';
      state.items = action.payload;
    })
    .addCase(fetchTodos.rejected, (state, action) => {
      state.status = 'error';
      state.error = action.error.message;
    });
}

function* fetchTodosSaga() {
  const todos = yield call(api.getTodos);
  yield put({ type: 'todos/loaded', payload: todos });
}
function* rootSaga() {
  yield takeEvery('todos/fetch', fetchTodosSaga);
}

